import { test, expect } from '@playwright/test';

/**
 * Downloads, Exports & Reproducibility Audit (Phase 10)
 * Tests every export format generated by the instrument:
 * NetCDF-4, GeoJSON FeatureCollection, Science Dossier, Jupyter IPYNB, and LaTeX.
 */
test.describe('Downloads, Exports & Reporting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard', { waitUntil: 'load' });
    const cookieBtn = page.getByRole('button', { name: /Accept Preferences/i });
    if (await cookieBtn.isVisible({ timeout: 1000 }).catch(() => false)) {
      await cookieBtn.click();
    }
    await expect(page.getByRole('button', { name: /Computing Trends.../i })).toBeHidden({ timeout: 30000 });
  });

  test('user can trigger NetCDF-4 export download', async ({ page }) => {
    const downloadPromise = page.waitForEvent('download', { timeout: 15000 });
    const netCdfBtn = page.locator("button:has-text('NetCDF-4')").first();
    await netCdfBtn.click();
    const download = await downloadPromise;
    expect(download.suggestedFilename()).toMatch(/\.nc$/);
  });

  test('user can trigger GeoJSON FeatureCollection export download', async ({ page }) => {
    const downloadPromise = page.waitForEvent('download', { timeout: 15000 });
    const geoJsonBtn = page.locator("button:has-text('GeoJSON')").first();
    await geoJsonBtn.click();
    const download = await downloadPromise;
    expect(download.suggestedFilename()).toMatch(/\.geojson$/);
  });

  test('user can trigger Science Dossier markdown export download', async ({ page }) => {
    const downloadPromise = page.waitForEvent('download', { timeout: 15000 });
    const dossierBtn = page.locator("button:has-text('Science Dossier')").first();
    await dossierBtn.click();
    const download = await downloadPromise;
    expect(download.suggestedFilename()).toMatch(/\.md$/);
  });

  test('user can trigger Jupyter Notebook export download', async ({ page }) => {
    const downloadPromise = page.waitForEvent('download', { timeout: 15000 });
    const ipynbBtn = page.locator("button:has-text('Jupyter Notebook')").first();
    await ipynbBtn.click();
    const download = await downloadPromise;
    expect(download.suggestedFilename()).toMatch(/\.ipynb$/);
  });

  test('user can open Technical Memo LaTeX modal and view formatted publication source', async ({ page }) => {
    const latexBtn = page.locator("button:has-text('Technical Memo')").first();
    await latexBtn.click();

    // Verify modal appears with LaTeX code content
    await expect(page.getByRole('heading', { name: /NASA Technical Memorandum/i })).toBeVisible({ timeout: 10000 });
    const codeArea = page.locator('pre, code, textarea');
    await expect(codeArea.first()).toBeVisible();

    // Dismiss with Close button or Escape
    await page.keyboard.press('Escape');
    await expect(page.getByRole('heading', { name: /NASA Technical Memorandum/i })).toBeHidden();
  });
});
